import React, { useEffect, useState } from "react";
import axios from "axios";
import { useParams } from "react-router-dom";

function ApartmentCard() {
    const { apartmentId } = useParams(); // Получаем apartmentId из URL
    const [apartment, setApartment] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        // Запрос к бэкенду для получения данных о квартире
        axios.get(`http://localhost:8000/api/apartments/${apartmentId}`)
            .then((response) => {
                setApartment(response.data);
                setLoading(false);
            })
            .catch((error) => {
                setError(error);
                setLoading(false);
            });
    }, [apartmentId]);

    // Отображение загрузки
    if (loading) return <div className="text-center">Loading...</div>;

    // Отображение ошибки
    if (error) return <div className="text-red-500">Error: {error.message}</div>;

    // Если квартира не найдена
    if (!apartment) return <div className="text-center">Apartment not found</div>;

    return (
        <div className="max-w-2xl mx-auto p-4 bg-white shadow-lg rounded-lg">
            {/* Заголовок */}
            <h1 className="text-2xl font-bold mb-4">{apartment.title}</h1>

            {/* Описание */}
            <p className="text-gray-600 mb-4">{apartment.description}</p>

            {/* Цена */}
            <p className="text-green-600 font-bold mb-4">
                Price per day: ${apartment.price_per_day}
            </p>

            {/* Местоположение */}
            {apartment.location && (
                <p className="mb-4">
                    <span className="font-semibold">Location:</span> {apartment.location}
                </p>
            )}

            {/* Удобства */}
            {apartment.amenities && (
                <div>
                    <h2 className="text-xl font-semibold mb-2">Amenities:</h2>
                    <ul className="list-disc list-inside">
                        {apartment.amenities.map((amenity, index) => (
                            <li key={index} className="text-gray-600">
                                {amenity}
                            </li>
                        ))}
                    </ul>
                </div>
            )}
        </div>
    );
}

export default ApartmentCard;
